# Generated by the offline AFL-UAV reproduction fixture.
import argparse
import heapq
import json
import math
import random


def read_problem(path: str) -> dict:
    with open(path, 'r') as f:
        raw = json.load(f)

    env = raw['environment']
    width = env['width']
    height = env['height']
    start = env['start']
    goal = env['goal']
    obstacles = env['obstacles']
    risk_zones = env.get('risk_zones', [])
    safety_distance = env['safety_distance']
    seed = env['seed']
    objective_weights = raw['objective_weights']
    grid_resolution = raw['grid_resolution']
    max_waypoints = raw['max_waypoints']

    if not (isinstance(width, (int, float)) and math.isfinite(width) and width > 0):
        raise ValueError('width must be positive and finite')
    if not (isinstance(height, (int, float)) and math.isfinite(height) and height > 0):
        raise ValueError('height must be positive and finite')
    if not (isinstance(start, list) and len(start) == 2 and all(isinstance(v, (int, float)) and math.isfinite(v) for v in start)):
        raise ValueError('start must be a list of two finite numbers')
    if not (isinstance(goal, list) and len(goal) == 2 and all(isinstance(v, (int, float)) and math.isfinite(v) for v in goal)):
        raise ValueError('goal must be a list of two finite numbers')
    if not (0 <= start[0] <= width and 0 <= start[1] <= height):
        raise ValueError('start must be within map bounds')
    if not (0 <= goal[0] <= width and 0 <= goal[1] <= height):
        raise ValueError('goal must be within map bounds')
    if not (isinstance(safety_distance, (int, float)) and math.isfinite(safety_distance) and safety_distance >= 0):
        raise ValueError('safety_distance must be a non-negative finite number')
    if not (isinstance(seed, int)):
        raise ValueError('seed must be an integer')

    if not isinstance(obstacles, list):
        raise ValueError('obstacles must be a list')
    cleaned_obstacles = []
    for obs in obstacles:
        if not isinstance(obs, dict):
            raise ValueError('each obstacle must be a dict')
        kind = obs.get('kind')
        if kind == 'circle':
            required = ['center', 'radius']
            if not all(k in obs for k in required):
                raise ValueError('circle obstacle missing required fields')
            center = obs['center']
            radius = obs['radius']
            if not (isinstance(center, list) and len(center) == 2 and all(isinstance(v, (int, float)) and math.isfinite(v) for v in center)):
                raise ValueError('circle center must be list of two finite numbers')
            if not (isinstance(radius, (int, float)) and math.isfinite(radius) and radius > 0):
                raise ValueError('circle radius must be positive and finite')
            cleaned_obstacles.append({'kind': 'circle', 'center': center, 'radius': radius})
        elif kind == 'rectangle':
            required = ['min_x', 'min_y', 'max_x', 'max_y']
            if not all(k in obs for k in required):
                raise ValueError('rectangle obstacle missing required fields')
            min_x, min_y, max_x, max_y = obs['min_x'], obs['min_y'], obs['max_x'], obs['max_y']
            for val in [min_x, min_y, max_x, max_y]:
                if not (isinstance(val, (int, float)) and math.isfinite(val)):
                    raise ValueError('rectangle bounds must be finite numbers')
            if min_x >= max_x or min_y >= max_y:
                raise ValueError('rectangle min bounds must be less than max bounds')
            cleaned_obstacles.append({'kind': 'rectangle', 'min_x': min_x, 'min_y': min_y, 'max_x': max_x, 'max_y': max_y})
        else:
            raise ValueError(f'unknown obstacle kind: {kind}')

    cleaned_risk_zones = []
    for rz in risk_zones:
        if not isinstance(rz, dict):
            raise ValueError('each risk zone must be a dict')
        required = ['min_x', 'min_y', 'max_x', 'max_y', 'weight']
        if not all(k in rz for k in required):
            raise ValueError('risk zone missing required fields')
        min_x, min_y, max_x, max_y, weight = rz['min_x'], rz['min_y'], rz['max_x'], rz['max_y'], rz['weight']
        for val in [min_x, min_y, max_x, max_y, weight]:
            if not (isinstance(val, (int, float)) and math.isfinite(val)):
                raise ValueError('risk zone values must be finite numbers')
        if min_x >= max_x or min_y >= max_y:
            raise ValueError('risk zone min bounds must be less than max bounds')
        if weight < 0:
            raise ValueError('risk zone weight must be non-negative')
        cleaned_risk_zones.append({'name': rz.get('name', f'risk_{len(cleaned_risk_zones)}'), 'min_x': min_x, 'min_y': min_y, 'max_x': max_x, 'max_y': max_y, 'weight': weight})

    required_weights = ['length', 'collision', 'risk', 'smoothness', 'waypoint']
    if not isinstance(objective_weights, dict):
        raise ValueError('objective_weights must be a dict')
    for w in required_weights:
        if w not in objective_weights:
            raise ValueError(f'missing objective weight: {w}')
        if not (isinstance(objective_weights[w], (int, float)) and math.isfinite(objective_weights[w]) and objective_weights[w] >= 0):
            raise ValueError(f'objective weight {w} must be non-negative and finite')

    if not (isinstance(grid_resolution, (int, float)) and math.isfinite(grid_resolution) and grid_resolution > 0):
        raise ValueError('grid_resolution must be positive and finite')
    if not (isinstance(max_waypoints, int) and max_waypoints >= 2):
        raise ValueError('max_waypoints must be an integer >= 2')

    problem = {
        'width': float(width),
        'height': float(height),
        'start': [float(start[0]), float(start[1])],
        'goal': [float(goal[0]), float(goal[1])],
        'obstacles': cleaned_obstacles,
        'risk_zones': cleaned_risk_zones,
        'safety_distance': float(safety_distance),
        'seed': seed,
        'objective_weights': {k: float(v) for k, v in objective_weights.items()},
        'grid_resolution': float(grid_resolution),
        'max_waypoints': max_waypoints,
        '_metrics': {}
    }
    return problem


def segment_collision_free(start, end, problem) -> bool:
    if '_metrics' in problem and problem['_metrics'] is not None:
        problem['_metrics']['collision_checks'] = problem['_metrics'].get('collision_checks', 0) + 1

    obstacles = problem.get('obstacles', [])
    safety_distance = problem.get('safety_distance', 0.0)

    sx, sy = start
    ex, ey = end
    dx = ex - sx
    dy = ey - sy
    seg_len_sq = dx * dx + dy * dy
    if seg_len_sq == 0.0:
        seg_len = 0.0
    else:
        seg_len = math.sqrt(seg_len_sq)

    for obs in obstacles:
        kind = obs.get('kind')
        if kind == 'circle':
            center = obs.get('center')
            radius = obs.get('radius')
            required_dist = radius + safety_distance
            cx, cy = center
            if seg_len_sq == 0.0:
                dist = math.hypot(sx - cx, sy - cy)
            else:
                t = ((cx - sx) * dx + (cy - sy) * dy) / seg_len_sq
                t = max(0.0, min(1.0, t))
                proj_x = sx + t * dx
                proj_y = sy + t * dy
                dist = math.hypot(cx - proj_x, cy - proj_y)
            if dist < required_dist:
                return False
        elif kind == 'rectangle':
            min_x = obs.get('min_x') - safety_distance
            max_x = obs.get('max_x') + safety_distance
            min_y = obs.get('min_y') - safety_distance
            max_y = obs.get('max_y') + safety_distance

            # Parameter interval where segment is inside expanded rectangle
            t0 = 0.0
            t1 = 1.0

            # Check x slab
            if abs(dx) < 1e-12:
                if sx < min_x or sx > max_x:
                    continue
            else:
                tx_min = (min_x - sx) / dx
                tx_max = (max_x - sx) / dx
                if tx_min > tx_max:
                    tx_min, tx_max = tx_max, tx_min
                if tx_max < t0 or tx_min > t1:
                    continue
                t0 = max(t0, tx_min)
                t1 = min(t1, tx_max)
                if t0 > t1:
                    continue

            # Check y slab
            if abs(dy) < 1e-12:
                if sy < min_y or sy > max_y:
                    continue
            else:
                ty_min = (min_y - sy) / dy
                ty_max = (max_y - sy) / dy
                if ty_min > ty_max:
                    ty_min, ty_max = ty_max, ty_min
                if ty_max < t0 or ty_min > t1:
                    continue
                t0 = max(t0, ty_min)
                t1 = min(t1, ty_max)
                if t0 > t1:
                    continue

            # Both slabs overlap => collision
            return False
        else:
            raise ValueError(f'unknown obstacle kind: {kind}')

    return True


def path_cost(path, problem) -> float:
    if 'max_evaluations' in problem and 'objective_evaluations' in problem.get('_metrics', {}):
        if problem['_metrics']['objective_evaluations'] >= problem['max_evaluations']:
            return float('inf')

    problem.setdefault('_metrics', {})
    problem['_metrics']['objective_evaluations'] = problem['_metrics'].get('objective_evaluations', 0) + 1
    weights = problem['objective_weights']
    length = 0.0
    collision_penalty = 0.0
    smoothness_penalty = 0.0
    risk = 0.0
    waypoint_penalty = max(0, len(path) - 2)
    if len(path) < 2:
        return weights['collision'] * 1000.0

    for i in range(len(path) - 1):
        dx = path[i+1][0] - path[i][0]
        dy = path[i+1][1] - path[i][1]
        seg_len = math.hypot(dx, dy)
        length += seg_len
        if not segment_collision_free(path[i], path[i+1], problem):
            collision_penalty += 1.0

    if len(path) >= 3:
        for i in range(1, len(path) - 1):
            v1 = (path[i][0] - path[i-1][0], path[i][1] - path[i-1][1])
            v2 = (path[i+1][0] - path[i][0], path[i+1][1] - path[i][1])
            mag1 = math.hypot(*v1)
            mag2 = math.hypot(*v2)
            if mag1 == 0.0 or mag2 == 0.0:
                smoothness_penalty += 1.0
            else:
                dot = v1[0] * v2[0] + v1[1] * v2[1]
                cos_angle = max(-1.0, min(1.0, dot / (mag1 * mag2)))
                ang = math.acos(cos_angle)
                smoothness_penalty += (ang / math.pi) ** 2

    for zone in problem.get('risk_zones', []):
        min_x, min_y = zone['min_x'], zone['min_y']
        max_x, max_y = zone['max_x'], zone['max_y']
        zone_weight = zone.get('weight', 1.0)
        for i in range(len(path) - 1):
            x1, y1 = path[i]
            x2, y2 = path[i+1]
            seg_dx = x2 - x1
            seg_dy = y2 - y1
            seg_len = math.hypot(seg_dx, seg_dy)
            if seg_len == 0.0:
                continue
            # Parameter interval for x inside [min_x, max_x]
            tx0, tx1 = 0.0, 1.0
            if abs(seg_dx) < 1e-12:
                if x1 < min_x or x1 > max_x:
                    continue
            else:
                tx_min = (min_x - x1) / seg_dx
                tx_max = (max_x - x1) / seg_dx
                if tx_min > tx_max:
                    tx_min, tx_max = tx_max, tx_min
                if tx_max < 0.0 or tx_min > 1.0:
                    continue
                tx0 = max(0.0, tx_min)
                tx1 = min(1.0, tx_max)
            # Parameter interval for y inside [min_y, max_y]
            ty0, ty1 = 0.0, 1.0
            if abs(seg_dy) < 1e-12:
                if y1 < min_y or y1 > max_y:
                    continue
            else:
                ty_min = (min_y - y1) / seg_dy
                ty_max = (max_y - y1) / seg_dy
                if ty_min > ty_max:
                    ty_min, ty_max = ty_max, ty_min
                if ty_max < 0.0 or ty_min > 1.0:
                    continue
                ty0 = max(0.0, ty_min)
                ty1 = min(1.0, ty_max)
            t0 = max(tx0, ty0)
            t1 = min(tx1, ty1)
            if t0 <= t1:
                risk += zone_weight * (t1 - t0) * seg_len

    total = (weights['length'] * length +
             weights['collision'] * collision_penalty +
             weights['risk'] * risk +
             weights['smoothness'] * smoothness_penalty +
             weights['waypoint'] * waypoint_penalty)
    return total


def initial_path(problem) -> list[list[float]]:
    width = problem['width']
    height = problem['height']
    res = problem['grid_resolution']
    start = tuple(problem['start'])
    goal = tuple(problem['goal'])

    # Generate grid points spanning [0, width] x [0, height], including edges
    xs = []
    x = 0.0
    while x <= width + 1e-9:
        xs.append(x)
        x += res
    if not xs or xs[-1] < width:
        xs.append(width)

    ys = []
    y = 0.0
    while y <= height + 1e-9:
        ys.append(y)
        y += res
    if not ys or ys[-1] < height:
        ys.append(height)

    nodes = set()
    for x in xs:
        for y in ys:
            nodes.add((x, y))
    nodes.add(start)
    nodes.add(goal)

    grid_nodes = set(nodes) - {start, goal}

    def heuristic(node):
        return math.hypot(node[0] - goal[0], node[1] - goal[1])

    def neighbors(node):
        x, y = node
        candidates = [start, goal]
        # Generate neighboring grid nodes: all grid points within one grid step in
        # each direction, using round to snap to nearest grid coordinate.
        for nx in xs:
            if nx < x - res - 1e-9 or nx > x + res + 1e-9:
                continue
            for ny in ys:
                if ny < y - res - 1e-9 or ny > y + res + 1e-9:
                    continue
                if (nx, ny) in grid_nodes or (nx, ny) == start or (nx, ny) == goal:
                    candidates.append((nx, ny))
        # Deduplicate and yield
        seen = set()
        for c in candidates:
            if c != node and c not in seen:
                seen.add(c)
                yield c

    open_heap = []
    heapq.heappush(open_heap, (heuristic(start), 0, start))
    came_from = {start: None}
    g_score = {start: 0.0}
    closed = set()

    metrics = problem.get('_metrics')
    while open_heap:
        f, g, current = heapq.heappop(open_heap)
        if current in closed:
            continue
        closed.add(current)
        if metrics is not None and isinstance(metrics, dict):
            metrics['node_expansions'] = metrics.get('node_expansions', 0) + 1

        if current == goal:
            # Reconstruct path
            path = []
            node = goal
            while node is not None:
                path.append([float(node[0]), float(node[1])])
                node = came_from[node]
            path.reverse()

            # Remove consecutive duplicates
            dedup_path = []
            for p in path:
                if not dedup_path or math.dist(dedup_path[-1], p) > 1e-12:
                    dedup_path.append(p)
            path = dedup_path

            # Simplify path while preserving feasibility
            simplified = [path[0]]
            i = 1
            while i < len(path) - 1:
                if segment_collision_free(simplified[-1], path[i + 1], problem):
                    i += 1
                else:
                    simplified.append(path[i])
                    i += 1
            # Ensure final segment to goal is collision-free
            if len(simplified) == 0 or math.dist(simplified[-1], path[-1]) > 1e-9:
                if segment_collision_free(simplified[-1], path[-1], problem):
                    simplified.append(path[-1])
                else:
                    # If direct connection fails, append intermediate points from path
                    simplified.extend(path[i:])
            # Final validation of all segments
            for a, b in zip(simplified, simplified[1:]):
                if not segment_collision_free(a, b, problem):
                    # Fallback to original search path
                    return [list(p) for p in path]
            # Remove consecutive duplicates again and ensure goal is included
            dedup = []
            for pt in simplified:
                if not dedup or math.dist(dedup[-1], pt) > 1e-12:
                    dedup.append(pt)
            if not dedup or math.dist(dedup[-1], path[-1]) > 1e-9:
                dedup.append(path[-1])
            return dedup

        for nb in neighbors(current):
            if nb in closed:
                continue
            if not segment_collision_free(list(current), list(nb), problem):
                continue
            tentative_g = g + math.hypot(nb[0] - current[0], nb[1] - current[1])
            if nb not in g_score or tentative_g < g_score[nb]:
                came_from[nb] = current
                g_score[nb] = tentative_g
                f_score = tentative_g + heuristic(nb)
                heapq.heappush(open_heap, (f_score, tentative_g, nb))

    raise RuntimeError('No feasible path found by deterministic grid search')


def destroy(path, rng) -> list[list[float]]:
    n = len(path)
    if n <= 4:
        return path.copy()
    rng = rng or random.Random(abs(hash(tuple(map(tuple, path)))))
    # At least two points must remain, and remove a contiguous block of 2..max_removable points.
    max_removable = max(2, (n - 3) // 2)
    if n >= 6:
        max_removable = (n - 2) // 2
    max_removable = min(max_removable, n - 3)
    if max_removable < 2:
        return path.copy()
    max_removable = min(max_removable, n - 2)  # ensure at least two points remain
    remove_count = rng.randint(2, max_removable)
    block_start = rng.randint(1, n - 2 - remove_count + 1)
    block_end = block_start + remove_count - 1
    new_path = path[:block_start] + path[block_end+1:]
    return new_path


def repair(original, candidate, problem, rng) -> list[list[float]]:
    def is_feasible(path):
        if len(path) < 2:
            return False
        if len(path) > problem['max_waypoints']:
            return False
        start = problem['start']
        goal = problem['goal']
        if math.dist(path[0], start) > 1e-9 or math.dist(path[-1], goal) > 1e-9:
            return False
        for p in path:
            if not (math.isfinite(p[0]) and math.isfinite(p[1])):
                return False
            if not (0.0 <= p[0] <= problem['width'] and 0.0 <= p[1] <= problem['height']):
                return False
        for i in range(len(path) - 1):
            if not segment_collision_free(path[i], path[i+1], problem):
                return False
        return True

    path = [list(p) for p in candidate]

    # If candidate is feasible, attempt to delete random waypoints to shorten it
    if is_feasible(path):
        if len(path) > 2:
            for _ in range(min(10, len(path) - 2)):
                if len(path) <= 2:
                    break
                idx = rng.randint(1, len(path) - 2)
                new_path = path[:idx] + path[idx+1:]
                if is_feasible(new_path):
                    return new_path
        return path

    # Candidate is infeasible, attempt repair by reconnecting segments
    if len(path) <= 3:
        return [list(p) for p in original]
    for _ in range(min(5, max(1, len(path) // 2))):
        if len(path) <= 3:
            break
        i = rng.randint(1, len(path) - 3)
        j = rng.randint(i + 1, len(path) - 2)
        if segment_collision_free(path[i], path[j], problem):
            new_path = path[:i+1] + path[j:]
            if is_feasible(new_path):
                return new_path

    # If repair fails, return original feasible path
    return [list(p) for p in original]


def validate_path(path, problem) -> bool:
    if not path or len(path) < 2:
        return False
    if len(path) > problem['max_waypoints']:
        return False
    tol = 1e-9
    start = problem['start']
    goal = problem['goal']
    if (abs(path[0][0] - start[0]) > tol or
        abs(path[0][1] - start[1]) > tol or
        abs(path[-1][0] - goal[0]) > tol or
        abs(path[-1][1] - goal[1]) > tol):
        return False
    width = problem['width']
    height = problem['height']
    for point in path:
        if not (math.isfinite(point[0]) and math.isfinite(point[1])):
            return False
        if point[0] < 0 or point[0] > width or point[1] < 0 or point[1] > height:
            return False
    for i in range(len(path) - 1):
        if not segment_collision_free(path[i], path[i+1], problem):
            return False
    return True


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument('--path', required=True)
    parser.add_argument('--iteration', type=int, default=100)
    parser.add_argument('--output', required=True)
    parser.add_argument('--seed', type=int, default=0)
    parser.add_argument('--max-evaluations', type=int, default=1000)
    args = parser.parse_args()
    problem = read_problem(args.path)
    problem['_metrics'] = {'objective_evaluations': 0, 'collision_checks': 0, 'node_expansions': 0}
    problem['max_evaluations'] = args.max_evaluations
    rng = random.Random(args.seed)
    initial = initial_path(problem)
    if not validate_path(initial, problem):
        raise RuntimeError('Initial path is infeasible')
    # Check budget before initial cost evaluation
    if problem['_metrics']['objective_evaluations'] >= args.max_evaluations:
        initial_cost = float('inf')
    else:
        initial_cost = path_cost(initial, problem)
    best_path = [list(p) for p in initial]
    best_cost = initial_cost
    iteration = 0
    while iteration < args.iteration and problem['_metrics']['objective_evaluations'] < args.max_evaluations:
        candidate = destroy(best_path, rng)
        if candidate is None:
            iteration += 1
            continue
        repaired = repair(best_path, candidate, problem, rng)
        if repaired is None:
            iteration += 1
            continue
        if not validate_path(repaired, problem):
            iteration += 1
            continue
        # Check budget before evaluating candidate
        if problem['_metrics']['objective_evaluations'] >= args.max_evaluations:
            break
        cost = path_cost(repaired, problem)
        if cost < best_cost - 1e-9:
            best_path = [list(p) for p in repaired]
            best_cost = cost
        iteration += 1
    if not validate_path(best_path, problem):
        raise RuntimeError('Best path became infeasible before output')
    result = {
        'status': 'success',
        'path': best_path,
        'initial_cost': initial_cost,
        'best_cost': best_cost,
        'iterations': iteration,
        'seed': args.seed,
        'objective_evaluations': problem['_metrics']['objective_evaluations'],
        'collision_checks': problem['_metrics']['collision_checks'],
        'node_expansions': problem['_metrics']['node_expansions']
    }
    with open(args.output, 'w') as f:
        json.dump(result, f)
    print(json.dumps(result))


if __name__ == '__main__':
    main()
